class TsharkInterfaces(object):
    S1 = 's1'
    UU = 'uu'


class TsharkStart(object):
    def __init__(self):
        self.tcpdump_procesess = []
        self.tcpdump_procesess_remote_host = []
        self.l1l2_logging_scripts_copied = False

    @staticmethod
    def start_tshark(
        log_filename, eth_interface, capture_filter='', alias='tshark_default_alias', log_dirpath=None, preferences=None
    ):
        """
        :param log_filename:
        :param eth_interface:
        :param capture_filter:
        :param alias:
        :param log_dirpath:
        :param preferences:
        :return:
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        OperatingSystem().create_directory(log_dirpath)
        logger.console("Start tshark on interface {} with {} filter".format(eth_interface, capture_filter))
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark.setup_tshark(
            interface=eth_interface, log_dir=log_dirpath, log_name=log_filename, alias=alias, preferences=preferences
        )
        ute_tshark.start_capturing(alias=alias, capture_filter=capture_filter)

    def start_collecting_L3_on_AP_remote_interface(
        self,
        log_filename_prefix='tcpdump',
        log_dirpath=None,
        alias=None,
        eth_interface='any sctp',
        ssh_ip='192.168.200.1',
        ssh_username='toor4nsn',
        ssh_password='oZPS0POrRieRtu',
    ):
        """
        :param log_filename_prefix
        :param log_dirpath
        :param eth_interface
        :param ssh_ip
        :param ssh_username
        :param ssh_password
        :return: os_process
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        log_filename = '{}.pcap'.format(log_filename_prefix)
        OperatingSystem().create_directory(log_dirpath)
        log_filepath = os.path.join(log_dirpath, log_filename)
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        if alias is None:
            alias = "remote_interface{}".format(timestamp)
            ute_tshark.setup_tshark(interface=eth_interface, alias=alias)
        else:
            ute_tshark.setup_tshark(interface=eth_interface, alias=alias)

        logger.console("Start tcpdump on interface: {}".format(eth_interface))

        cmd_tcpdump = (
            'sshpass -p {} ssh '
            '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
            '{}@{} \"tcpdump -s 0 -U -n -B 16384 '
            '-w - -i {}\" > {}'.format(ssh_password, ssh_username, ssh_ip, eth_interface,
                                       log_filepath)
        )
        tcpdump_process = subprocess.Popen([cmd_tcpdump], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
        self.tcpdump_procesess.append(tcpdump_process)
        return tcpdump_process, log_filepath, alias

    def start_tcpdump_on_remote_interface(
        self,
        log_filename_prefix='tcpdump',
        log_dirpath=None,
        alias=None,
        eth_interface='any sctp',
        ssh_ip='192.168.255.129',
        ssh_username='toor4nsn',
        ssh_password='oZPS0POrRieRtu',
        remote_host=None
    ):
        """
        :param log_filename_prefix
        :param log_dirpath
        :param eth_interface
        :param ssh_ip
        :param ssh_username
        :param ssh_password
        :return: os_process
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        if remote_host:
            log_filename_prefix = 'remote_host_F1_E1_RRC'
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        log_filename = '{}.pcap'.format(log_filename_prefix)
        OperatingSystem().create_directory(log_dirpath)
        log_filepath = os.path.join(log_dirpath, log_filename)
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        if alias is None:
            alias = "remote_interface{}".format(timestamp)
            ute_tshark.setup_tshark(interface=eth_interface, alias=alias)
        else:
            ute_tshark.setup_tshark(interface=eth_interface, alias=alias)

        logger.console("Start tcpdump on interface: {}".format(eth_interface))
        if not remote_host:
            main_board_type = ta5g_enb().get_enb_main_board_type()
            if main_board_type == "ASIK":
                gnb_hostname = subprocess.check_output(
                    "sshpass -p {} ssh  -q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null "
                    "-o UserKnownHostsFile=/dev/null {}@{} 'echo $HOSTNAME'".format(ssh_password, ssh_username, ssh_ip),
                    shell=True).decode(encoding='UTF-8')
                last_octet_of_ip = 1020 if 'fct-4a' in gnb_hostname else 20
                logger.info("Asik detected, binding asik slave to local address to collect pcaps directly on asik slave.")
                cmd_bind_asik_slave_to_localhost = (
                    'sshpass -p {} ssh '
                    '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                    '{}@{} -T -L 8989:[fd5f:4268:2387:a881:40:43ff:fe80:{}]:22'.format(ssh_password, ssh_username, ssh_ip,
                                                                                       last_octet_of_ip))
                ssh_tunnel = subprocess.Popen([cmd_bind_asik_slave_to_localhost], stdout=subprocess.PIPE, shell=True,
                                              preexec_fn=os.setsid)
                self.tcpdump_procesess.append(ssh_tunnel)
                BuiltIn().sleep(time_=1, reason="Wait for Binding to complete.")
                cmd_tcpdump = (
                    'sshpass -p {} ssh '
                    '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                    '{}@localhost -p 8989 \"tcpdump -s 0 -U -n -B 16384 '
                    '-w - -i {}\" > /dev/shm/temp_pcap_{}'.format(ssh_password, ssh_username, eth_interface, timestamp)
                )
            else:
                cmd_tcpdump = (
                    'sshpass -p {} ssh '
                    '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                    '{}@{} \"tcpdump -s 0 -U -n -B 16384 '
                    '-w - -i {}\" > /dev/shm/temp_pcap_{}'.format(ssh_password, ssh_username, ssh_ip, eth_interface,
                                                                  timestamp)
                )
            cmd_redirect_pcap = 'tail -f /dev/shm/temp_pcap_{} 2>/dev/null > {}'.format(timestamp, log_filepath)
            tcpdump_process = subprocess.Popen([cmd_tcpdump], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
            tail_process = subprocess.Popen([cmd_redirect_pcap], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
            self.tcpdump_procesess.extend([tail_process, tcpdump_process])
        else:
            cmd_ssh1 = (
                'sshpass -p ute ssh '
                '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                'ute@{}'.format(remote_host))
            cmd_ssh2 = (
                'sshpass -p {} ssh '
                '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
                '{}@{} "tcpdump -s 0 -U -n -B 16384 -w - -i {}"'.format(ssh_password, ssh_username, ssh_ip, eth_interface))
            cmd_tcpdump = f"{cmd_ssh1} '{cmd_ssh2}' > /dev/shm/temp_pcap_remote_host{timestamp}"
            cmd_redirect_pcap = 'tail -f /dev/shm/temp_pcap_remote_host{} 2>/dev/null > {}'.format(timestamp, log_filepath)
            tcpdump_process = subprocess.Popen([cmd_tcpdump], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
            tail_process = subprocess.Popen([cmd_redirect_pcap], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
            self.tcpdump_procesess_remote_host.extend([tail_process, tcpdump_process])

        return tcpdump_process, log_filepath, alias

    @staticmethod
    def stop_tshark(alias='tshark_default_alias'):
        """
        :param alias:
        :return:
        """
        logger.console('Stopping tshark with alias {}'.format(alias))
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        ute_tshark.stop_capturing(alias=alias)
        ute_tshark.teardown_tshark(alias=alias)

    def stop_tcpdump_on_remote_interface(self):
        """
        Kills processes started with start_tcpdump_on_remote_interface and start_collecting_l1l2_logs:
        :return:
        """
        for process in self.tcpdump_procesess:
            os.killpg(os.getpgid(process.pid), signal.SIGTERM)
        self.tcpdump_procesess = []
        os.system("rm /dev/shm/temp_pcap_*")

    def stop_tcpdump_on_remote_host(self):
        """
        Kills processes started with start_tcpdump_on_remote_interface:
        :return:
        """
        for process in self.tcpdump_procesess_remote_host:
            os.killpg(os.getpgid(process.pid), signal.SIGTERM)
        self.tcpdump_procesess_remote_host = []
        os.system("rm /dev/shm/temp_pcap_remote_host*")

    def start_collecting_l1l2_logs(self, log_dirpath=None, ssh_username='toor4nsn', ssh_password='oZPS0POrRieRtu'):
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        gnb_log_filename = 'gNB_L1L2.pcap'
        gnb_log_filepath = os.path.join(log_dirpath, gnb_log_filename)
        bb_board_type = ta5g_enb().get_enb_baseband_board_type()
        hw_type = ta5g_iphy().get_hw_type()
        if self.l1l2_logging_scripts_copied is False:
            subprocess.check_call(
                'rsync -r /home/ute/Auto5G/testsuite/RRM/5G_SW_WRO/resources/scripts/gnbMirroring.sh '
                '/home/ute/Auto5G/testsuite/RRM/5G_SW_WRO/resources/scripts/gnbMirroringConfig.sh '
                '192.168.255.129:/user/toor4nsn/scripts/',
                shell=True,
            )
            self.l1l2_logging_scripts_copied = True

        cmd_gnb_mirroring = (
            'sshpass -p {} ssh '
            '-q -o StrictHostKeyChecking=no -o GlobalKnownHostsFile=/dev/null -o UserKnownHostsFile=/dev/null '
            '{}@192.168.255.129 \"sh /user/toor4nsn/scripts/gnbMirroring.sh --bb_board_type={} --topology={}\" > {}'.format(
                ssh_password, ssh_username, bb_board_type, hw_type, gnb_log_filepath
            )
        )

        gnb_mirroring_process = subprocess.Popen(
            [cmd_gnb_mirroring], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid
        )
        self.tcpdump_procesess.extend([gnb_mirroring_process])
        BuiltIn().sleep(time_=10, reason="Waiting for start tcpdump on AP and gNB.")

    def start_default_tshark_on_s1_mme_and_uu_interfaces(self, log_dirpath=None):
        """
        :param log_dirpath:
        :return:
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        default_s1_mme_sctp = ta5g_tshark_filters().DEFAULT_S1_MME_SCTP
        default_uu_less_1000 = ta5g_tshark_filters().DEFAULT_UU_LESS_1000
        self.start_tshark(
            log_filename='core_external_NG_X2_S1_{}.pcap'.format(timestamp),
            eth_interface='eth3',
            capture_filter=default_s1_mme_sctp,
            alias="default_s1_x2",
            log_dirpath=log_dirpath,
        )
        self.start_tshark(
            log_filename='UU_{}.pcap'.format(timestamp),
            eth_interface='eth4',
            capture_filter=default_uu_less_1000,
            alias="default_uu",
            log_dirpath=log_dirpath,
        )

