    def start_default_tshark_on_s1_mme_and_uu_interfaces_for_testcase(
        self, log_dirpath=None, s1_capture_filter=None, uu_capture_filter=None, preferences_s1=None, preferences_uu=None
    ):
        """
        :param log_dirpath:
        :param s1_capture_filter:
        :param uu_capture_filter:
        :return:
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        if s1_capture_filter is None:
            s1_capture_filter = ta5g_tshark_filters().DEFAULT_S1_MME_SCTP
        if uu_capture_filter is None:
            uu_capture_filter = ta5g_tshark_filters().DEFAULT_UU_LESS_1000
        test_name = ta5g_interface_tools().get_robot_test_name()
        s1_alias = "s1_{}".format(test_name)
        uu_alias = "uu_{}".format(test_name)
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        self.start_tshark(
            log_filename='core_external_NG_X2_S1_{}_{}.pcap'.format(test_name, timestamp),
            eth_interface='eth3',
            capture_filter=s1_capture_filter,
            alias=s1_alias,
            log_dirpath=log_dirpath,
            preferences=preferences_s1,
        )
        self.start_tshark(
            log_filename='UU_{}_{}.pcap'.format(test_name, timestamp),
            eth_interface='eth4',
            capture_filter=uu_capture_filter,
            alias=uu_alias,
            log_dirpath=log_dirpath,
            preferences=preferences_uu,
        )
        return [s1_alias, uu_alias]

