    def stop_existing_default_tshark_on_s1_mme_and_uu_interfaces(self):
        """
        :return:
        """
        try:
            self.stop_tshark(alias="default_s1_x2")
        except ExecutionFailed as error:
            logger.console(error)
        try:
            self.stop_tshark(alias="default_uu")
        except ExecutionFailed as error:
            logger.console(error)

    def stop_default_tshark_on_s1_mme_and_uu_interfaces_for_testcase(self):
        """
        :return:
        """
        test_name = ta5g_interface_tools().get_robot_test_name()
        self.__stop_tshark_alias(TsharkInterfaces().S1, test_name)
        self.__stop_tshark_alias(TsharkInterfaces().UU, test_name)

    def __stop_tshark_alias(self, alias, test_name):
        alias = "{}_{}".format(alias, test_name)
        try:
            self.stop_tshark(alias=alias)
        except ExecutionFailed as error:
            logger.console(error)

    def start_logged_data_traffic_for_given_period_of_time(
        self, ue_id, bearer_id, direction, throughput, period, traffic_id=1
    ):
        """
        :param ue_id:
        :param bearer_id:
        :param direction:
        :param throughput:
        :param period:
        :param traffic_id:
        :return:
        """
        log_dirpath = OperatingSystem().join_path(
            ta5g_interface_tools().get_robot_output_dir(), ta5g_interface_tools().get_robot_test_name(), 'tshark'
        )
        prefix = "data_traffic"
        s1_alias = self.start_tshark_for_s1_mme_interface(log_dirpath=log_dirpath, log_filename_prefix=prefix)
        uu_alias = self.start_tshark_for_uu_interface(log_dirpath=log_dirpath, log_filename_prefix=prefix)
        self.__start_data_traffic_for_given_period_of_time(
            ue_id=ue_id,
            bearer_id=bearer_id,
            direction=direction,
            throughput=throughput,
            period=period,
            traffic_id=traffic_id,
        )
        BuiltIn().get_library_instance('ute_tshark').stop_capturing(alias=s1_alias)
        BuiltIn().get_library_instance('ute_tshark').stop_capturing(alias=uu_alias)
        return [s1_alias, uu_alias]

    def start_logged_data_traffic_for_both_directions_for_given_period_of_time(
        self, ue_id, bearer_id, throughput, period, traffic_id=1
    ):
        """
        :param ue_id:
        :param bearer_id:
        :param throughput:
        :param period:
        :param traffic_id:
        :return:
        """
        log_dirpath = OperatingSystem().join_path(ta5g_interface_tools().get_robot_output_dir(), ['tshark'])
        prefix = "data_traffic"
        s1_alias = self.start_tshark_for_s1_mme_interface(log_dirpath=log_dirpath, log_filename_prefix=prefix)
        uu_alias = self.start_tshark_for_uu_interface(log_dirpath=log_dirpath, log_filename_prefix=prefix)
        self.__start_data_traffic_for_both_directions_for_given_period_of_time(
            ue_id=ue_id, bearer_id=bearer_id, throughput=throughput, period=period, traffic_id=traffic_id
        )
        BuiltIn().get_library_instance('ute_tshark').stop_capturing(alias=s1_alias)
        BuiltIn().get_library_instance('ute_tshark').stop_capturing(alias=uu_alias)
        return [s1_alias, uu_alias]

    @staticmethod
    def __start_data_traffic_for_given_period_of_time(
        ue_id, bearer_id, direction, throughput, period, traffic_id=1, optional_parameters=''
    ):
        """
        Should be implemented in ta5g_data_trafic
        """
        ute_wtssim = BuiltIn().get_library_instance('ute_wtssim')
        ute_wtssim.execute_egate_command_and_wait_for_data(
            "trf_data_start ue={} id={} dir={} trf_id={} {} {}".format(
                ue_id, bearer_id, direction, traffic_id, throughput, optional_parameters
            )
        )
        BuiltIn().sleep(period)
        ute_wtssim.execute_egate_command("trf_data_stop ue=${}".format(ue_id))

    @staticmethod
    def __start_data_traffic_for_both_directions_for_given_period_of_time(
        ue_id, bearer_id, throughput, period, traffic_id=1
    ):
        """
        :param ue_id:
        :param bearer_id:
        :param throughput:
        :param period:
        :param traffic_id:
        :return:
        """
        ute_wtssim = BuiltIn().get_library_instance('ute_wtssim')
        ute_wtssim.execute_egate_command_and_wait_for_data(
            "trf_data_start ue={} id={} dir=dl trf_id={} {}".format(ue_id, bearer_id, traffic_id, throughput)
        )
        ute_wtssim.execute_egate_command_and_wait_for_data(
            "trf_data_start ue={} id={} dir=ul trf_id={} {}".format(ue_id, bearer_id, traffic_id, throughput)
        )
        BuiltIn().sleep(period)
        ute_wtssim.execute_egate_command("trf_data_stop ue=${}".format(ue_id))

    def get_active_cpif(self):
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vnfcs_states = vcu_connection.get_vnfcs_states()
            logger.info(vnfcs_states)
        for vnfcs in vnfcs_states:
            try:
                if 'cpif' in vnfcs['name'] and vnfcs['two_nactivity'] == 'active':
                    cpif_name = vnfcs['name']
                    logger.info(cpif_name)
                    return cpif_name
                elif 'cpif' in vnfcs['name'] and vnfcs['two_nactivity'] == 'notapplicable':
                    cpif_name = vnfcs['name']
                    logger.info(cpif_name)
                    return cpif_name
            except Exception:
                if 'cpif' in vnfcs['name']:
                    cpif_name = vnfcs['name']
                    logger.info(cpif_name)
                    return cpif_name

    def start_tcpdump_on_remote_interface_aic(
        self,
        log_filename_prefix='tcpdump',
        log_dirpath=None,
        alias=None
    ):
        """
        Start tcpdump on remote interface aic and collect pcap on ports:
        36422, 38472, 38462, 38412, 38422
        :param log_filename_prefix
        :param log_dirpath
        :param alias
        """
        tl = BuiltIn().get_variable_value("${tl}")
        VCU_MASTER_IP = tl.cloud_hostings[0].master_node.ssh_connection_details.addr
        VCU_NAMESPACE = tl.cloud_hostings[0].namespace
        active_cpif = self.get_active_cpif()
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        log_filename = '{}.pcap'.format(log_filename_prefix)
        OperatingSystem().create_directory(log_dirpath)
        log_filepath = os.path.join(log_dirpath, log_filename)
        ute_tshark = BuiltIn().get_library_instance('ute_tshark')
        if alias is None:
            alias = "remote_interface{}".format(timestamp)
            ute_tshark.setup_tshark(interface='any', alias=alias)
        else:
            ute_tshark.setup_tshark(interface='any', alias=alias)
        with ta5g_admin_operations().connect_to_vcu_aic() as vcu_connection:
            vcu_version = vcu_connection.get_active_software_version()
        logger.console("Start tcpdump on interface: ")
        if '25R3' not in vcu_version:
            cmd_tcpdump = 'sshpass -p system123 ssh core@{} -p 22 "kubectl exec -n {} -c \
                ctr-nwmgmt {} -- /usr/bin/execwithcaps -q\
                 -- tcpdump -i sctp -i any port 36422 or port 38472 or port 38462 or port 38412 or port 38422 \
                 -s 0 -U -n -w -" > /dev/shm/temp_pcap_{}'.format(VCU_MASTER_IP, VCU_NAMESPACE,
                                                                  active_cpif,
                                                                  timestamp)
        else:
            cmd_tcpdump = 'sshpass -p system123 ssh core@{} -p 22 "kubectl exec -n {} -c \
                  ctr-{}-nwmgmt {}\
                  -- tcpdump -i sctp -i any port 36422 or port 38472 or port 38462 or port 38412 or port 38422 \
                  -s 0 -U -n -w -" > /dev/shm/temp_pcap_{}'.format(VCU_MASTER_IP, VCU_NAMESPACE,
                                                                   VCU_NAMESPACE, active_cpif,
                                                                   timestamp)
        cmd_redirect_pcap = 'tail -f /dev/shm/temp_pcap_{} 2>/dev/null > {}'.format(timestamp, log_filepath)
        tcpdump_process = subprocess.Popen([cmd_tcpdump], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
        tail_process = subprocess.Popen([cmd_redirect_pcap], stdout=subprocess.PIPE, shell=True, preexec_fn=os.setsid)
        self.tcpdump_procesess.extend([tail_process, tcpdump_process])
        return tcpdump_process, log_filepath, alias

    def start_default_tshark_on_s1_mme_and_uu_interfaces_aic(self, log_dirpath=None):
        """
        Start tshark and collect core_external_NG_X2_S1 and UU pcap in aic
        :param log_dirpath:
        :return:
        """
        if log_dirpath is None:
            log_dirpath = ta5g_interface_tools().get_robot_output_dir()
        timestamp = ta5g_file_system.get_timestamp_for_filesystem()
        default_s1_mme_sctp = ta5g_tshark_filters().DEFAULT_S1_MME_SCTP
        default_uu_less_1000 = ta5g_tshark_filters().DEFAULT_UU_LESS_1000
        self.start_tshark(
            log_filename='core_external_NG_X2_S1_{}.pcap'.format(timestamp),
            eth_interface='any',
            capture_filter=default_s1_mme_sctp,
            alias="default_s1_x2",
            log_dirpath=log_dirpath,
        )
        self.start_tshark(
            log_filename='UU_{}.pcap'.format(timestamp),
            eth_interface='eth4',
            capture_filter=default_uu_less_1000,
            alias="default_uu",
            log_dirpath=log_dirpath,
        )

    def start_pcaps_collection_for_test_subcase(self, output_dirpath, subcase_name):
        self.start_tshark_for_uu_interface(log_dirpath=os.path.join(output_dirpath, 'tshark'), log_filename_prefix=subcase_name,
                                           alias='default_uu_subcase')
        self.start_tshark_for_s1_mme_interface(log_dirpath=os.path.join(output_dirpath, 'tshark'), log_filename_prefix=subcase_name,
                                               alias='default_s1_x2_subcase')
        self.start_tcpdump_on_remote_interface(log_filename_prefix="{}_gnb_F1_E1_RRC".format(subcase_name),
                                               log_dirpath=os.path.join(output_dirpath, 'tshark'), alias='tcpdump_subcase')

    def stop_pcaps_collection_for_test_subcase(self):
        self.stop_tcpdump_on_remote_interface()
        self.stop_tshark(alias='default_uu_subcase')
        self.stop_tshark(alias='default_s1_x2_subcase')
        self.stop_tshark(alias='tcpdump_subcase')
